void mainImage(out vec4 fragColor, in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec2 cells=vec2(max(U.p0.x,4.0),max(U.p0.x,4.0)*iResolution.y/iResolution.x);
 vec2 at=(floor(uv*cells)+0.5)/cells;
 vec3 c=texture(iChannel0,at).rgb;
 float levels=max(U.p0.z,2.0);
 c=floor(clamp(c,0.0,1.0)*(levels-1.0)+0.5)/(levels-1.0);
 vec2 f=fract(uv*cells); float edge=min(min(f.x,f.y),min(1.0-f.x,1.0-f.y));
 float mask=smoothstep(clamp(U.p0.y,0.0,0.3),clamp(U.p0.y,0.0,0.3)+0.02,edge);
 fragColor=vec4(mix(vec3(0.015),c,mask),1.0);
}
